// ResourceServiceHandler is an implementation of the pylabrobot.resource.v1.ResourceService
// service.
type ResourceServiceHandler interface {
	// Return the full resource tree rooted at the given resource (or the deck if empty).
	GetTree(context.Context, *connect.Request[v1.GetTreeRequest]) (*connect.Response[v1.ResourceTree], error)
	// Return the flat data for a single resource by name.
	GetResource(context.Context, *connect.Request[v1.ResourceByNameRequest]) (*connect.Response[v1.ResourceData], error)
	// Check whether a resource with the given name exists on the deck.
	HasResource(context.Context, *connect.Request[v1.ResourceByNameRequest]) (*connect.Response[v1.BoolResponse], error)
	// Return the single-channel trash area resource.
	GetTrashArea(context.Context, *connect.Request[v1.Empty]) (*connect.Response[v1.ResourceData], error)
	// Return the 96-channel trash area resource.
	GetTrashArea96(context.Context, *connect.Request[v1.Empty]) (*connect.Response[v1.ResourceData], error)
	// Get the location of a resource relative to another resource, with anchor offsets.
	GetLocationWrt(context.Context, *connect.Request[v1.GetLocationWrtRequest]) (*connect.Response[v1.Coordinate], error)
	// Get the absolute (deck-space) location of a resource, with anchor offsets.
	GetAbsoluteLocation(context.Context, *connect.Request[v1.GetAbsoluteLocationRequest]) (*connect.Response[v1.Coordinate], error)
	// Get the cumulative rotation of a resource in deck-space.
	GetAbsoluteRotation(context.Context, *connect.Request[v1.GetAbsoluteRotationRequest]) (*connect.Response[v1.Rotation], error)
	// Get the rotation-aware bounding-box size of a resource.
	GetAbsoluteSize(context.Context, *connect.Request[v1.GetAbsoluteSizeRequest]) (*connect.Response[v1.Size], error)
	// Get the highest known z-coordinate point of a resource and its children.
	GetHighestPoint(context.Context, *connect.Request[v1.GetHighestPointRequest]) (*connect.Response[v1.FloatResponse], error)
	// Batch version of GetLocationWrt for multiple resource pairs at once.
	BatchGetLocationWrt(context.Context, *connect.Request[v1.BatchGetLocationWrtRequest]) (*connect.Response[v1.BatchCoordinateResponse], error)
	// Compute the liquid volume in a well given a liquid height.
	ComputeVolumeFromHeight(context.Context, *connect.Request[v1.ComputeVolumeHeightRequest]) (*connect.Response[v1.FloatResponse], error)
	// Compute the liquid height in a well given a liquid volume.
	ComputeHeightFromVolume(context.Context, *connect.Request[v1.ComputeVolumeHeightRequest]) (*connect.Response[v1.FloatResponse], error)
	// Check whether a resource supports height/volume conversion functions.
	SupportsComputeHeightVolume(context.Context, *connect.Request[v1.ResourceByNameRequest]) (*connect.Response[v1.BoolResponse], error)
	// Check whether a plate currently has a lid attached.
	HasLid(context.Context, *connect.Request[v1.HasLidRequest]) (*connect.Response[v1.BoolResponse], error)
	// Get the tip currently sitting on a tip spot.
	GetTip(context.Context, *connect.Request[v1.GetTipRequest]) (*connect.Response[v1.TipData], error)
	// Get the current volume tracker state (volume, pending, max, disabled) for a container.
	GetVolumeTrackerState(context.Context, *connect.Request[v1.ResourceByNameRequest]) (*connect.Response[v1.VolumeTrackerState], error)
	// Record a pending liquid removal from a container's volume tracker.
	RemoveLiquid(context.Context, *connect.Request[v1.TrackerOpRequest]) (*connect.Response[v1.Empty], error)
	// Record a pending liquid addition to a container's volume tracker.
	AddLiquid(context.Context, *connect.Request[v1.TrackerOpRequest]) (*connect.Response[v1.Empty], error)
	// Batch version of RemoveLiquid for multiple containers at once.
	BatchRemoveLiquid(context.Context, *connect.Request[v1.BatchTrackerOpRequest]) (*connect.Response[v1.Empty], error)
	// Batch version of AddLiquid for multiple containers at once.
	BatchAddLiquid(context.Context, *connect.Request[v1.BatchTrackerOpRequest]) (*connect.Response[v1.Empty], error)
	// Get the current tip tracker state (has_tip, tip data, disabled) for a tip spot.
	GetTipTrackerState(context.Context, *connect.Request[v1.ResourceByNameRequest]) (*connect.Response[v1.TipTrackerState], error)
	// Remove the tip from a tip spot's tracker (e.g. after a pick-up).
	RemoveTip(context.Context, *connect.Request[v1.TipTrackerOpRequest]) (*connect.Response[v1.Empty], error)
	// Add a new tip to a tip spot's tracker (e.g. after a return).
	AddTip(context.Context, *connect.Request[v1.TipTrackerOpRequest]) (*connect.Response[v1.Empty], error)
	// Commit pending volume tracker changes for the given containers.
	CommitVolumeTrackers(context.Context, *connect.Request[v1.CommitRollbackRequest]) (*connect.Response[v1.Empty], error)
	// Roll back pending volume tracker changes for the given containers.
	RollbackVolumeTrackers(context.Context, *connect.Request[v1.CommitRollbackRequest]) (*connect.Response[v1.Empty], error)
	// Commit pending tip tracker changes for the given tip spots.
	CommitTipTrackers(context.Context, *connect.Request[v1.CommitRollbackRequest]) (*connect.Response[v1.Empty], error)
	// Roll back pending tip tracker changes for the given tip spots.
	RollbackTipTrackers(context.Context, *connect.Request[v1.CommitRollbackRequest]) (*connect.Response[v1.Empty], error)
	// Re-parent a child resource under a new parent at the given location.
	AssignChild(context.Context, *connect.Request[v1.AssignChildRequest]) (*connect.Response[v1.Empty], error)
	// Remove a resource from its current parent.
	UnassignChild(context.Context, *connect.Request[v1.UnassignChildRequest]) (*connect.Response[v1.Empty], error)
}

